function makeResult(overrides = {}) {
  return {
    status: 'success',
    created: 0,
    updated: 0,
    deleted: 0,
    warnings: [],
    errors: [],
    summary: {},
    ...overrides
  };
}

function getUserErrors(error) {
  return error?.details?.userErrors || [];
}

function hasHandleConflict(error) {
  return getUserErrors(error).some((userError) =>
    String(userError.message).includes('Handle has already been taken')
  );
}

async function syncArticles({ config, client }) {
  const result = makeResult();
  const destinationBlogs = await client.destination.articles.listBlogs();
  const destinationBlogIdsByHandle = new Map(
    destinationBlogs.map((blog) => [blog.handle, blog.id])
  );
  const sourceArticles = await client.source.articles.listAll();
  const destinationArticles = await client.destination.articles.listAll();

  const missingBlogs = [];
  for (const article of sourceArticles) {
    if (!destinationBlogIdsByHandle.has(article.blog.handle)) {
      missingBlogs.push(article.blog);
    }
  }

  if (missingBlogs.length > 0) {
    const uniqueBlogs = Array.from(
      new Map(
        missingBlogs.map((blog) => [blog.handle, `${blog.title} (${blog.handle})`])
      ).values()
    );

    return makeResult({
      status: 'failed',
      errors: [
        `Cannot sync articles. Missing destination blogs: ${uniqueBlogs.join(', ')}`
      ],
      summary: {
        sourceCount: sourceArticles.length,
        destinationCount: destinationArticles.length
      }
    });
  }

  for (const sourceArticle of sourceArticles) {
    const destinationArticle = destinationArticles.find(
      (article) => article.handle === sourceArticle.handle
    );
    const destinationBlogId = destinationBlogIdsByHandle.get(sourceArticle.blog.handle);

    try {
      if (destinationArticle) {
        if (!config.createOnly) {
          await client.destination.articles.update(
            destinationArticle.id,
            sourceArticle,
            destinationBlogId
          );
          result.updated += 1;
        }
      } else if (!config.updateOnly) {
        try {
          await client.destination.articles.create(sourceArticle, destinationBlogId);
          result.created += 1;
        } catch (error) {
          if (!hasHandleConflict(error)) {
            throw error;
          }

          const conflictingArticle = destinationArticles.find(
            (article) => article.handle === sourceArticle.handle
          );

          if (!conflictingArticle) {
            throw error;
          }

          await client.destination.articles.update(
            conflictingArticle.id,
            sourceArticle,
            destinationBlogId
          );
          result.updated += 1;
        }
      }
    } catch (error) {
      result.errors.push(
        `Error processing "${sourceArticle.title}": ${error.message}`
      );
    }
  }

  if (config.cleanDestination && !config.createOnly && !config.updateOnly) {
    const sourceHandles = new Set(sourceArticles.map((article) => article.handle));

    for (const destinationArticle of destinationArticles) {
      if (sourceHandles.has(destinationArticle.handle)) {
        continue;
      }

      try {
        await client.destination.articles.delete(destinationArticle.id);
        result.deleted += 1;
      } catch (error) {
        result.errors.push(
          `Error deleting "${destinationArticle.title}": ${error.message}`
        );
      }
    }
  }

  result.status = result.errors.length > 0 ? 'failed' : 'success';
  result.summary = {
    sourceCount: sourceArticles.length,
    destinationCount: destinationArticles.length
  };

  return result;
}

module.exports = {
  syncArticles
};
